import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";

export type Theme = "light" | "dark";

export interface ThemeContextValue {
  theme: Theme;
  setTheme: (theme: Theme) => void;
  toggleTheme: () => void;
}

export const ThemeContext =
  createContext<ThemeContextValue | null>(
    null
  );

export function ThemeProvider({
  children,
}: {
  children: ReactNode;
}) {
  const [theme, setTheme] =
    useState<Theme>("light");

  useEffect(() => {
    const savedTheme =
      localStorage.getItem(
        "task-app-theme"
      ) as Theme | null;

    if (
      savedTheme === "light" ||
      savedTheme === "dark"
    ) {
      setTheme(savedTheme);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(
      "task-app-theme",
      theme
    );
  }, [theme]);

  function toggleTheme() {
    setTheme((prev) =>
      prev === "light"
        ? "dark"
        : "light"
    );
  }

  return (
    <ThemeContext.Provider
      value={{
        theme,
        setTheme,
        toggleTheme,
      }}
    >
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme(): ThemeContextValue {
  const ctx = useContext(ThemeContext);

  if (!ctx) {
    throw new Error(
      "useTheme must be used within ThemeProvider"
    );
  }

  return ctx;
}

import {
  createContext,
  useContext,
  type ReactNode,
} from "react";
import useLocalStorage from "../hooks/useLocalStorage";

export type Theme = "light" | "dark";

export interface ThemeContextValue {
  theme: Theme;
  setTheme: (theme: Theme) => void;
  toggleTheme: () => void;
}

export const ThemeContext =
  createContext<ThemeContextValue | null>(
    null
  );

export function ThemeProvider({
  children,
}: {
  children: ReactNode;
}) {
  const [theme, setTheme] =
    useLocalStorage<Theme>(
      "task-app-theme",
      "light"
    );

  function toggleTheme() {
    setTheme((prev) =>
      prev === "light"
        ? "dark"
        : "light"
    );
  }

  return (
    <ThemeContext.Provider
      value={{
        theme,
        setTheme,
        toggleTheme,
      }}
    >
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme(): ThemeContextValue {
  const ctx = useContext(ThemeContext);

  if (!ctx) {
    throw new Error(
      "useTheme must be used within ThemeProvider"
    );
  }

  return ctx;
}

import {
  useEffect,
  useMemo,
  useState,
  useCallback,
} from "react";
import TaskList from "./TaskList";
import TaskForm from "./TaskForm";
import FilterBar from "./FilterBar";
import StatsPanel from "./StatsPanel";
import type { Task } from "./TaskList";

import {
  ADD_TASK,
  UPDATE_TASK,
  TOGGLE_TASK,
  type TaskAction,
} from "../reducers/taskReducer";

interface TaskAppProps {
  tasks: Task[];
  dispatch?: React.Dispatch<TaskAction>;
  showForm?: boolean;
  onDelete?: (id: string | number) => void;
  showFilterBar?: boolean;
  showStatsPanel?: boolean;
  countFormat?: string;
  linkToTaskDetail?: boolean;
}

export default function TaskApp({
  tasks,
  dispatch,
  showForm,
  onDelete,
  showFilterBar,
  showStatsPanel,
}: TaskAppProps) {
  const [filter, setFilter] = useState<
    "all" | "active" | "completed"
  >("all");

  const [sortOrder, setSortOrder] =
    useState("recent");

  const [selectedCategory, setSelectedCategory] =
    useState("All categories");

  const [searchText, setSearchText] =
    useState("");

  const [
    debouncedSearchText,
    setDebouncedSearchText,
  ] = useState("");

  const [isSearching, setIsSearching] =
    useState(false);

  const [editingId, setEditingId] = useState<
    string | number | null
  >(null);

  const categories = [
    ...new Set(
      tasks
        .map((task) => task.category)
        .filter(Boolean)
    ),
  ];

  useEffect(() => {
    setIsSearching(true);

    const timer = setTimeout(() => {
      setDebouncedSearchText(searchText);
      setIsSearching(false);
    }, 300);

    return () => clearTimeout(timer);
  }, [searchText]);

  const handleAddTask = useCallback(
    (task: Task) => {
      if (!dispatch) return;

      dispatch({
        type: ADD_TASK,
        payload: task,
      });
    },
    [dispatch]
  );

  const handleToggle = useCallback(
    (id: string | number) => {
      if (!dispatch) return;

      dispatch({
        type: TOGGLE_TASK,
        payload: id,
      });
    },
    [dispatch]
  );

  const handleUpdateTask = useCallback(
    (
      id: string | number,
      updates: {
        title: string;
        description: string;
        priority: string;
      }
    ) => {
      if (!dispatch) return;

      if (!updates.title.trim()) {
        return;
      }

      dispatch({
        type: UPDATE_TASK,
        payload: {
          id,
          ...updates,
        },
      });

      setEditingId(null);
    },
    [dispatch]
  );

  const priorityValue: Record<
    string,
    number
  > = {
    High: 3,
    Medium: 2,
    Low: 1,
  };

  const sortedTasks = useMemo(() => {
    let filteredTasks =
      filter === "all"
        ? tasks
        : filter === "active"
        ? tasks.filter(
            (task) => !task.completed
          )
        : tasks.filter(
            (task) => task.completed
          );

    if (
      selectedCategory !==
      "All categories"
    ) {
      filteredTasks = filteredTasks.filter(
        (task) =>
          task.category ===
          selectedCategory
      );
    }

    filteredTasks = filteredTasks.filter(
      (task) =>
        task.title
          .toLowerCase()
          .includes(
            debouncedSearchText.toLowerCase()
          ) ||
        task.description
          .toLowerCase()
          .includes(
            debouncedSearchText.toLowerCase()
          )
    );

    return [...filteredTasks].sort(
      (a, b) => {
        if (sortOrder === "high") {
          return (
            priorityValue[b.priority] -
            priorityValue[a.priority]
          );
        }

        if (sortOrder === "low") {
          return (
            priorityValue[a.priority] -
            priorityValue[b.priority]
          );
        }

        if (
          sortOrder ===
          "alphabetical"
        ) {
          return a.title
            .toLowerCase()
            .localeCompare(
              b.title.toLowerCase()
            );
        }

        if (sortOrder === "due-date") {
          if (!a.dueDate && !b.dueDate)
            return 0;

          if (!a.dueDate) return 1;

          if (!b.dueDate) return -1;

          return (
            new Date(
              a.dueDate
            ).getTime() -
            new Date(
              b.dueDate
            ).getTime()
          );
        }

        return 0;
      }
    );
  }, [
    tasks,
    filter,
    selectedCategory,
    debouncedSearchText,
    sortOrder,
  ]);

  const stats = useMemo(() => {
    const total = tasks.length;

    const completed = tasks.filter(
      (task) => task.completed
    ).length;

    const active = total - completed;

    const overdue = tasks.filter(
      (task) =>
        !task.completed &&
        task.dueDate &&
        new Date(
          task.dueDate
        ).getTime() < Date.now()
    ).length;

    const completedPercentage =
      total === 0
        ? 0
        : Math.round(
            (completed / total) * 100
          );

    return {
      total,
      completed,
      active,
      overdue,
      completedPercentage,
    };
  }, [tasks]);

  return (
    <main>
      {showForm && (
        <TaskForm onAddTask={handleAddTask} />
      )}

      {showFilterBar && (
        <FilterBar
          filter={filter}
          onFilterChange={setFilter}
          sortOrder={sortOrder}
          onSortChange={setSortOrder}
          searchText={searchText}
          onSearchChange={setSearchText}
          onClearSearch={() => {
            setSearchText("");
            setDebouncedSearchText("");
          }}
          categories={categories}
          selectedCategory={
            selectedCategory
          }
          onCategoryChange={
            setSelectedCategory
          }
        />
      )}

      {showStatsPanel && (
        <StatsPanel
          total={stats.total}
          completed={stats.completed}
          active={stats.active}
          overdue={stats.overdue}
          completedPercentage={
            stats.completedPercentage
          }
        />
      )}

      {isSearching &&
        searchText !==
          debouncedSearchText && (
          <div id="searching-indicator">
            Searching...
          </div>
        )}

      <div id="task-count">
        Showing {sortedTasks.length} of{" "}
        {tasks.length} tasks
      </div>

      {sortedTasks.length === 0 ? (
        <div id="filter-empty-message">
          No tasks found
        </div>
      ) : (
        <TaskList
          tasks={sortedTasks}
          onToggle={handleToggle}
          onDelete={onDelete}
          onUpdateTask={handleUpdateTask}
          editingId={editingId}
          setEditingId={setEditingId}
        />
      )}
    </main>
  );
}

import {
  Component,
  type ErrorInfo,
  type ReactNode,
} from "react";

interface ErrorBoundaryProps {
  children: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

export default class ErrorBoundary extends Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  constructor(props: ErrorBoundaryProps) {
    super(props);

    this.state = {
      hasError: false,
    };
  }

  static getDerivedStateFromError(
    _error: Error
  ): ErrorBoundaryState {
    return {
      hasError: true,
    };
  }

  componentDidCatch(
    error: Error,
    errorInfo: ErrorInfo
  ) {
    void error;
    void errorInfo;
  }

  handleRetry = () => {
    this.setState({
      hasError: false,
    });
  };

  render() {
    if (this.state.hasError) {
      return (
        <div id="error-boundary-fallback">
          <h2>Something went wrong</h2>

          <p>Please try again.</p>

          <button
            id="error-retry"
            onClick={this.handleRetry}
          >
            Retry
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}
